import{fetchCohortJSON}from'./current-cohort-loader.js';
import{priorityLabels}from'./cohort-049-meta.js';
import{featureDefinitions as definitions,featureGroups,cohortGroups,cohortRow,filterCohort,cohortDistribution,scopeLabels}from'./cohort-features.js';
import{cohortCSV}from'./cohort-matrix-export.js';
import{authClient,getPrivateReviewCases}from'./firebase-client.js?v=0.47.0';
const $=id=>document.getElementById(id),h=x=>String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;'),labels=Object.fromEntries(featureGroups.map(g=>[g.id,g.label])),cohortLabels=Object.fromEntries(cohortGroups.map(g=>[g.id,g.label])),axes=['R','I','A','S','E','C'];
const metadataHTML=r=>r.cohort049?'<p class="detail-note">'+h(r.cohort049.kind==='diagnostic'?'Diagnostic variant · paired control':'New 0.49 base profile')+' · '+h(cohortLabels[r.phase]||r.phase)+(r.cohort049.intervention?' · '+h(r.cohort049.intervention):'')+(r.cohort049.description?' · '+h(r.cohort049.description):'')+(r.cohort049.baseId?' · Parent: <a href="./cohort-matrix.html?query='+encodeURIComponent(r.cohort049.baseId)+'&amp;cohort=all-rows&amp;view=profiles">'+h(r.cohort049.baseId)+' →</a>':'')+'</p>':'';
let snapshot,publicRows=[],privateRows=[],filtered=[],view='distribution',userId=null,generation=0;
const allRows=()=>[...publicRows,...privateRows],filters=()=>({query:$('search').value,cohort:$('cohort').value,feature:$('feature').value}),truncate=(v,n=95)=>v.length>n?v.slice(0,n-1)+'…':v;
function saveFilters(){const u=new URL(location.href);for(const[k,v]of Object.entries({...filters(),group:$('group').value,view}))if(v&&v!=='all'&&!(k==='view'&&v==='distribution'))u.searchParams.set(k,v);else u.searchParams.delete(k);history.replaceState(null,'',u);}
function evidenceHTML(items){return items.map(e=>'<blockquote class="evidence"><small>'+h(e.label)+' · '+h(e.path)+'</small>'+h(e.text)+'</blockquote>').join('');}
function openDialog(html){$('detail-content').innerHTML=html;if(!$('detail').open)$('detail').showModal();$('detail').scrollTop=0;}
function openFeature(id,cohort){const d=definitions.find(x=>x.id===id),rows=filtered.filter(r=>(cohort==='all'||r.phase===cohort)&&(d.kind==='score'?r.interest.complete:r.features[id]?.length));openDialog('<h2 id="detail-title">'+h(d.label)+'</h2><p>'+rows.length+' contributing models · '+h(cohort==='all'?'Full selection':cohortLabels[cohort])+'</p><p class="detail-note">'+h(featureGroups.find(g=>g.id===d.group).note)+'</p><ul class="match-list">'+rows.map(r=>'<li><button data-model="'+h(r.id)+'">'+h(r.name)+' →</button> <small>'+h(r.id)+' · '+h(cohortLabels[r.phase])+'</small>'+(d.kind==='score'?'<p>'+h(axes[d.axis])+': '+r.scores[d.axis]+' /40 · recorded interest, not aptitude.</p>':evidenceHTML(r.features[id]))+'</li>').join('')+'</ul>');}
const sectionNames={background:'Background',currentLife:'Current life',selfDescription:'Self-description',openQuestions:'Open questions',variationTags:'Author’s variation tags',timeline:'Life history'};
const fieldName=k=>({cultureLanguages:'Family, culture & languages',accessOpportunities:'Access to opportunities',demonstratedSkills:'Described skills',unfamiliarActivities:'Unfamiliar activities',practicalConstraints:'Practical constraints',finances:'Household finances'}[k]||k.replace(/[A-Z]/g,c=>' '+c.toLowerCase()).replace(/^./,c=>c.toUpperCase()));
function valueHTML(v){return Array.isArray(v)?'<ul>'+v.map(x=>'<li>'+h(typeof x==='object'?JSON.stringify(x):x)+'</li>').join('')+'</ul>':h(typeof v==='object'?JSON.stringify(v,null,2):v||'Not stated');}
function profile(id,group){const r=allRows().find(x=>x.id===id);if(!r)return;const b=r.biography;let html='<h2 id="detail-title">'+h(r.name)+'</h2><p>'+h(r.id)+' · '+h(cohortLabels[r.phase])+' · fictional model · age '+h(b.age??'not stated')+' · pronouns '+h(b.pronouns||'not stated')+'</p><div class="detail-links"><a href="./model-match-chart.html?query='+encodeURIComponent(r.id)+(r.cohort049?.kind==='diagnostic'?'&amp;cohort=diagnostic049':'')+'">Matches, answers & choices →</a><a href="./model-lab.html?case='+encodeURIComponent(r.id)+'#history">Complete model history →</a>'+(r.source.url?'<a href="'+h(r.source.url)+'">Public source JSON ↗</a>':'<span>Owner-only · loaded through sign-in</span>')+'</div>';
html+=metadataHTML(r);
if(group){html+='<section class="profile-block"><h3>'+h(labels[group])+' · coded evidence</h3><p>'+h(featureGroups.find(g=>g.id===group)?.note)+'</p>';const ds=definitions.filter(d=>d.group===group&&r.features[d.id]?.length);html+=ds.map(d=>'<details><summary>'+h(d.label)+'</summary>'+evidenceHTML(r.features[d.id])+'</details>').join('')||'<p>No topic coded in this group. Read the full narrative below; this does not mean the trait or condition is absent.</p>';html+='</section>';}
html+='<section class="profile-block"><h3>Recorded interests & optional answers</h3><p>'+axes.map((a,i)=>a+' '+r.scores[i]+'/40').join(' · ')+' · '+r.interest.answered+'/60 answered</p><p class="detail-note">Interest scores describe preferences. Narrative strengths and optional experience answers are simulated descriptions. Authored answers may be omitted from the main replay; applied answers show what it used. Neither is measured aptitude.</p><dl class="fact"><dt>Authored optional experience</dt><dd>'+h(Object.keys(r.authoredSkills||{}).length?JSON.stringify(r.authoredSkills,null,2):'Not recorded')+'</dd><dt>Applied optional experience</dt><dd>'+h(Object.keys(r.recordedSkills||{}).length?JSON.stringify(r.recordedSkills,null,2):'Not applied')+'</dd><dt>Applied priorities</dt><dd>'+h((r.appliedPriorities||[]).map(k=>priorityLabels[k]||k).join(' · ')||'None applied')+'</dd><dt>Other recorded preferences</dt><dd>'+h(JSON.stringify(r.recordedPreferences,null,2))+'</dd></dl></section>';
for(const[k,v]of Object.entries(b)){if(['name','age','pronouns','id'].includes(k))continue;html+='<section class="profile-block"><h3>'+h(sectionNames[k]||fieldName(k))+'</h3>';if(k==='timeline')html+=(v||[]).map(t=>'<h4>Age '+h(t.ages)+'</h4><p>'+h(t.story)+'</p>').join('');else if(v&&typeof v==='object'&&!Array.isArray(v))html+='<dl>'+Object.entries(v).map(([f,x])=>'<div class="fact"><dt>'+h(fieldName(f))+'</dt><dd>'+valueHTML(x)+'</dd></div>').join('')+'</dl>';else html+=valueHTML(v);html+='</section>';}
html+='<p class="small">'+h(r.source.classification)+(r.source.sha256?' · SHA-256 '+h(r.source.sha256):'')+'</p>';openDialog(html);}
const profileColumns=[{id:'demographic',title:'Age, pronouns & location',groups:['demographic','geography']},{id:'family',title:'Family, culture & finances',groups:['family','culture','finance']},{id:'riasec',title:'Six interests /40',groups:['riasec']},{id:'interest',title:'Interests & activities',groups:['interest']},{id:'skill',title:'Described skills',groups:['skill']},{id:'motivation',title:'Motivations',groups:['motivation']},{id:'style',title:'Characteristics & style',groups:['style']},{id:'mental',title:'Mental-health topics',groups:['mental']},{id:'learning',title:'Learning & physical access',groups:['learning','physical']},{id:'support',title:'School & supports',groups:['school','support']},{id:'constraint',title:'Constraints & unfamiliar work',groups:['constraint']},{id:'recording',title:'Other features & evidence',groups:['recording']}];
function cell(r,c){let items=[];const b=r.biography,cl=b.currentLife||{};if(c.id==='riasec')return'<button class="cell-open" data-model="'+h(r.id)+'" data-group="riasec" aria-label="'+h(r.name)+' · interest details"><span class="score-grid">'+axes.map((a,i)=>'<span style="--score:'+r.scores[i]/40+'">'+a+'<b>'+r.scores[i]+'</b></span>').join('')+'</span></button>';
if(c.id==='demographic'&&c.groups.length>1)items=['Age '+(b.age??'not stated'),b.pronouns||'Pronouns not stated',b.background?.geography||'Location not stated'];
else if(c.id==='skill')items=cl.demonstratedSkills||[];
else if(c.id==='motivation')items=[...cl.motivations||[],...cl.ambitions||[]];
else if(c.id==='constraint')items=[...cl.practicalConstraints||[],...cl.unfamiliarActivities||[]];
else if(c.id==='family'&&c.groups.length>1)items=[b.background?.family,b.background?.cultureLanguages,b.background?.finances].filter(Boolean);
else if(c.id==='recording')items=[...(b.variationTags||[]),'Authored optional experience: '+Object.keys(r.authoredSkills||{}).length,'Applied optional experience: '+Object.keys(r.recordedSkills||{}).length];
else items=c.groups.flatMap(g=>scopeLabels(r,g));
return'<button class="cell-open" data-model="'+h(r.id)+'" data-group="'+h(c.id)+'" title="Open full profile and source evidence">'+(items.length?items.slice(0,3).map(x=>'<span class="tag '+(['mental','learning','physical'].includes(c.id)?'health':'')+'">'+h(truncate(x))+'</span>').join(''):'<span class="muted">Not stated / not coded</span>')+(items.length>3?'<span class="more">+'+(items.length-3)+' more · open profile →</span>':'<span class="more">Profile & evidence →</span>')+'</button>';}
function render(){if(!snapshot)return;filtered=filterCohort(allRows(),filters());const group=$('group').value;saveFilters();$('distribution-view').setAttribute('aria-pressed',view==='distribution');$('profiles-view').setAttribute('aria-pressed',view==='profiles');$('model-total').textContent=filtered.length;$('cohort-note').textContent=allRows().length+' available, including diagnostic variants · '+privateRows.length+' owner-only available';const ages=filtered.map(r=>r.biography.age).filter(Number.isFinite),unique=[...new Set(ages)].sort((a,b)=>a-b);$('age-range').textContent=unique.length?(unique.length===1?unique[0]+' only':unique[0]+'–'+unique.at(-1)):'Not stated';$('age-note').textContent=ages.length+' of '+filtered.length+' have a stated age. Legacy is a batch, not an age group.';$('skill-total').textContent=filtered.filter(r=>Object.keys(r.authoredSkills||{}).length).length+' authored · '+filtered.filter(r=>Object.keys(r.recordedSkills||{}).length).length+' applied';
$('matrix-status').textContent=filtered.length+' of '+allRows().length+' models · '+(group==='all'?'all feature groups':labels[group]);$('export-profiles').disabled=!filtered.length;$('export-distribution').disabled=!filtered.length;
if(view==='distribution'){const data=cohortDistribution(filtered,group);$('matrix-heading').textContent='Distribution across cohorts';$('matrix-note').textContent='Each cell shows the share of its selected cohort, with count / denominator underneath. Darker green means a larger share. Blue cells are mean interest scores out of 40. Themes overlap and do not sum to 100%. Click a count to see its exact evidence.';let prior='';$('matrix-table').innerHTML='<table class="distribution"><caption class="sr-only">Feature distribution within the current selection</caption><thead><tr><th scope="col">Feature / narrative topic</th>'+data.groups.map(g=>'<th scope="col">'+h(g.label)+'<small style="display:block">'+g.n+' models'+(g.id==='private'&&!privateRows.length?' · sign in':'')+'</small></th>').join('')+'</tr></thead><tbody>'+data.features.map(({definition:d,cells})=>{let band='';if(d.group!==prior){prior=d.group;const g=featureGroups.find(x=>x.id===d.group);band='<tr class="band"><th colspan="'+(data.groups.length+1)+'">'+h(g.label)+'<small>'+h(g.note)+'</small></th></tr>';}return band+'<tr><th scope="row">'+h(d.label)+'</th>'+cells.map(c=>'<td class="cell">'+(c.value===null?'<span class="unavailable">—</span>':'<button class="heat '+(d.kind==='score'?'score-cell':'')+'" style="--shade:'+(d.kind==='score'?c.value/40:c.value)+'" data-feature="'+h(d.id)+'" data-cohort="'+c.cohort+'" aria-label="'+h(d.label+' · '+(c.cohort==='all'?'Full selection':cohortLabels[c.cohort])+': '+(d.kind==='score'?c.value.toFixed(1)+' out of 40':c.count+' of '+c.n))+'">'+(d.kind==='score'?c.value.toFixed(1):Math.round(c.value*1000)/10+'%')+'<small>'+(d.kind==='score'?c.count+' scored / '+c.n:c.count+' / '+c.n)+'</small></button>')+'</td>').join('')+'</tr>';}).join('')+'</tbody></table>';$('table-help').textContent='Scroll within the matrix to compare every feature. Zero means no matching source mention, not a negative clinical or trait assessment. A dash means there are no models in that column.';}
else{const cols=group==='all'?profileColumns:[{id:group,title:labels[group],groups:[group]}];$('matrix-heading').textContent='Every model, side by side';$('matrix-note').textContent='One row per model. This overview abbreviates long descriptions; open any cell for every original biography field, timeline, unfamiliar activity and source. Select a feature group for a narrower comparison.';$('matrix-table').innerHTML='<table class="profiles"'+(cols.length===1?' style="min-width:600px"':'')+'><thead><tr><th scope="col">Fictional model</th>'+cols.map(c=>'<th scope="col">'+h(c.title)+'</th>').join('')+'</tr></thead><tbody>'+filtered.map(r=>'<tr><th scope="row"><button class="name" data-model="'+h(r.id)+'">'+h(r.name)+' →</button><span class="model-meta">'+h(r.id)+'<br>'+h(cohortLabels[r.phase])+'</span>'+metadataHTML(r)+'</th>'+cols.map(c=>'<td class="profile-cell">'+cell(r,c)+'</td>').join('')+'</tr>').join('')+(!filtered.length?'<tr><td colspan="'+(cols.length+1)+'" class="empty">No models in this selection.'+($('cohort').value==='private'?' Sign in with the owner account to include private models.':'')+'</td></tr>':'')+'</tbody></table>';$('table-help').textContent='All selected models are shown. Headers and names stay in place while you scroll. Descriptions are not measured skills or clinical classifications.';}}
function download(kind){const blob=new Blob(['\uFEFF'+cohortCSV(filtered,{kind,group:$('group').value,cohort:$('cohort').value})],{type:'text/csv;charset=utf-8'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='fieldguide-cohort-'+kind+'-'+filtered.length+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function clearPrivate(){privateRows=[];$('detail').close();$('detail-content').replaceChildren();render();}
async function loadPrivate(){const request=++generation,session=await authClient.getSession(),user=session.data?.user;if(request!==generation)return;userId=user?.id||null;clearPrivate();$('sign-in').hidden=!!user;$('sign-out').hidden=!user;if(user){$('access-status').textContent=publicRows.length+' public models. Loading authorized owner-only models…';try{const cases=await getPrivateReviewCases(),current=(await authClient.getSession()).data?.user;if(request!==generation||current?.id!==user.id)return;privateRows=cases.map(c=>cohortRow({...c,phase:'private'}));$('access-status').textContent=publicRows.length+' public + '+privateRows.length+' owner-only models · complete cohort available.';}catch{if(request!==generation)return;$('access-status').textContent=publicRows.length+' public models. This account cannot load owner-only models.';}}else $('access-status').textContent=publicRows.length+' public models. Sign in with the owner account to include six owner-only models.';render();}
$('close-detail').onclick=()=>{$('detail').close();$('detail-content').replaceChildren();};$('detail').addEventListener('click',e=>{if(e.target===$('detail'))$('close-detail').click();});
document.addEventListener('click',e=>{const model=e.target.closest('[data-model]'),feature=e.target.closest('[data-feature]');if(model)profile(model.dataset.model,model.dataset.group);else if(feature)openFeature(feature.dataset.feature,feature.dataset.cohort);});
for(const id of['cohort','group','feature'])$(id).addEventListener('change',render);$('search').addEventListener('input',render);$('reset').onclick=()=>{for(const id of['cohort','group','feature'])$(id).value='all';$('search').value='';view='distribution';$('matrix-table').scrollTop=0;render();};
$('distribution-view').onclick=()=>{view='distribution';render();};$('profiles-view').onclick=()=>{view='profiles';render();};$('export-distribution').onclick=()=>download('distribution');$('export-profiles').onclick=()=>download('profiles');$('sign-in').onclick=async()=>{try{await authClient.googleSignIn();await loadPrivate();}catch{$('access-status').textContent='Use owner sign-in on the published Fieldguide site to include the six private profiles.';}};$('sign-out').onclick=async()=>{++generation;clearPrivate();await authClient.signOut();await loadPrivate();};
try{snapshot=await fetchCohortJSON('./cohort-matrix-data.json.gz');publicRows=[...snapshot.rows,...(await Promise.all((snapshot.rowParts||[]).map(async part=>{const data=await fetchCohortJSON(part.url);if(data.rows.length!==part.rows)throw Error('Cohort matrix part does not agree.');return data.rows;}))).flat()];$('cohort').innerHTML+=[...cohortGroups].map(g=>'<option value="'+g.id+'">'+h(g.label)+'</option>').join('');$('group').innerHTML+=featureGroups.map(g=>'<option value="'+g.id+'">'+h(g.label)+'</option>').join('');$('feature').innerHTML+=featureGroups.map(g=>'<optgroup label="'+h(g.label)+'">'+definitions.filter(d=>d.group===g.id&&d.kind!=='score').map(d=>'<option value="'+h(d.id)+'">'+h(d.label)+'</option>').join('')+'</optgroup>').join('');const p=new URL(location.href).searchParams;for(const id of['cohort','group','feature'])if([...$(id).options].some(o=>o.value===p.get(id)))$(id).value=p.get(id);$('search').value=p.get('query')||'';if(p.get('view')==='profiles')view='profiles';
$('source-content').innerHTML='<p>Release '+h(snapshot.version)+' · built '+h(new Date(snapshot.generatedAt).toLocaleDateString())+'. All 1,000 base profiles (172 original and 828 structured synthetic cases) and 12 diagnostic variants are available; the six owner-only cases load after sign-in. The default selection and exports include base profiles only. Choose Base profiles + diagnostic variants to include paired controls. These authored cases are test coverage, not a representative population of students.</p><p>Source grain: one fictional model. '+definitions.length+' inspectable feature rows across '+featureGroups.length+' groups. Counts deduplicate each model within each row; a person can appear in several rows. Group filters change the visible features; cohort, search and feature restrictions change the denominator.</p><p><strong>Known gaps:</strong> all public models are age 16; authored optional experience and answers applied in the main replay are reported separately. These simulated experience answers are not measured skills. No standardized clinical assessments or validated aptitude measurements are recorded. Gender, ethnicity, family income and current clinical diagnoses are not inferred from names, pronouns or narrative context. School subject performance, grades and unfamiliar activities remain in the full source when stated.</p><p>Keyword coding is an editorial index to help find the original text, not a validated assessment. Read exact evidence before interpreting a count. Health/history tags can describe relatives, past events or questions; they do not establish a student condition. Explicit leading negative statements are excluded from health counts, but their full wording is retained in the profile. No coded mention means unknown, not absent.</p><p>Full profiles CSV contains every biography field for the selected models, plus recorded interest scores and optional answers. Distribution CSV contains the selected feature group and cohort denominators. Owner-only exports include authorized rows only while signed in.</p><p><a href="./cohort-matrix-data.json.gz">Public snapshot, source hashes & methods · JSON ↗</a> · <a href="./docs/cohort-expansion-049-2026-10-19.md.html">New cohorts, controls & provenance →</a> · <a href="./docs/cohort-matrix-048-2026-10-19.md.html">Original coding notes →</a></p><details><summary>Inspect all coding rules</summary>'+featureGroups.map(g=>'<h3>'+h(g.label)+'</h3><p>'+h(g.note)+'</p><ul>'+definitions.filter(d=>d.group===g.id).map(d=>'<li>'+h(d.label)+' · '+(d.pattern?'<code>'+h(d.scope)+' → /'+h(d.pattern.source)+'/i</code>':d.kind==='score'?'Mean of complete recorded interest profiles':'Recorded fact: '+h(d.fact)+(d.value?' · '+h(d.value):''))+'</li>').join('')+'</ul>').join('')+'</details>';
render();await loadPrivate();authClient.watch(next=>{if((next?.id||null)!==userId){++generation;clearPrivate();loadPrivate();}});
}catch(e){$('access-status').textContent=e.message||'The cohort matrix could not load.';}
